files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #000000;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;

  padding-top: 94px;
  font-family: 'Open Sans', sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink);
}

.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  color: var(--vt-ink);
  line-height: inherit;
  font-weight: 600;
}

.root h1,
.root h2 {
  font-weight: 700;
}

.root h1 {
  font-size: 48px;
  line-height: normal;
}

.root h2 {
  font-size: 36px;
}

.root h3 {
  font-size: 32px;
}

.root h4 {
  font-size: 28px;
}

.root h5 {
  font-size: 24px;
}

.root h6 {
  font-size: 22px;
}

.root p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
}

.root a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: all 0.3s;
}

.root a:hover {
  color: var(--vt-accent);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

/* Navigation */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--vt-surface);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  padding: 20px 0;
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 15px;
}

.logo {
  display: block;
}

.brand {
  white-space: nowrap;
}

.navLinks {
  display: flex;
  gap: 1.5rem;
}

.navLinks a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  padding: 15px 0;
}

.navLinks a:hover {
  color: var(--vt-ink);
}

/* Hero */
.hero {
  position: relative;
  overflow: hidden;
  background: var(--vt-surface);
}

.heroTrack {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: 580px;
  -webkit-overflow-scrolling: touch;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  height: 100%;
}

.heroSlide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  background: var(--vt-surface);
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  padding: 1.5rem 2.5rem;
  width: 50%;
  box-shadow: 0 0 20px rgba(0,0,0,0.1);
}

.heroText h1 {
  margin: 0 0 0.5rem;
  color: var(--vt-ink);
}

.kicker {
  color: var(--vt-accent);
  font-weight: 600;
  font-size: 1.2rem;
}

.heroText p {
  color: var(--vt-ink-soft);
  margin-bottom: 1rem;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  pointer-events: auto;
  font-weight: 600;
  line-height: 40px;
  position: relative;
  padding: 0 30px;
  box-sizing: border-box;
  margin: 0;
  user-select: none;
  overflow: hidden;
  border-radius: 0;
  text-transform: uppercase;
  margin-right: 1.5rem;
}

.customLink::before {
  content: attr(data-hover);
  background-color: var(--vt-line);
  color: var(--vt-accent);
  position: absolute;
  top: 100%;
  bottom: 0;
  left: 0;
  transition: all 300ms cubic-bezier(0.19, 1, 0.56, 1);
  right: 0;
  text-align: center;
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
  margin: 0;
}

/* Sections */
.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 15px;
}

.aboutGrid {
  display: block;
}

.aboutText h2 {
  margin-bottom: 1.5rem;
  color: var(--vt-ink);
}

.aboutText p {
  color: var(--vt-ink-soft);
  line-height: 1.8;
  margin-bottom: 1rem;
}

/* Gallery */
.gallerySection {
  background: var(--vt-surface);
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
}

.galleryItem {
  flex: 1 1 50%;
  padding: 0;
  overflow: hidden;
}

.galleryImage {
  width: 100%;
  height: auto;
  display: block;
}

/* Timeline */
.sectionTitle {
  text-align: center;
  margin-bottom: 3rem;
  color: var(--vt-ink);
}

.timeline {
  position: relative;
}

.timeline::before {
  content: "";
  display: block;
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  z-index: 1;
  transform: translateX(-50%);
}

.timelineNode {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 2rem;
  position: relative;
}

.timelineNode.odd {
  flex-direction: row;
}

.timelineNode.even {
  flex-direction: row-reverse;
}

.timelineContent {
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
  border-radius: 0 0 0.25rem 0.25rem;
  padding: 0;
  width: 45%;
}

.timelineContent h3 {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  margin: 0;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
  font-size: 1.5rem;
}

.timelineContent p {
  padding: 10px 30px;
  color: var(--vt-ink-soft);
  margin: 0;
}

.timelineNode.odd .timelineContent {
  text-align: right;
}

.timelineNode.even .timelineContent {
  text-align: left;
}

.timelineNode.odd .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode.even .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineIconWrap {
  width: 80px;
  height: 80px;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0,0,0,0.175);
  border-radius: 50%;
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: center;
  align-items: center;
  flex-shrink: 0;
}

.timelineIcon::after {
  content: "";
  display: block;
  width: 12px;
  height: 12px;
  background: var(--vt-accent);
  border-radius: 50%;
}

.timelineDate {
  width: 30%;
  padding: 1.5rem 0;
  color: var(--vt-ink-soft);
  font-size: 16px;
}

.timelineNode.odd .timelineDate {
  text-align: left;
}

.timelineNode.even .timelineDate {
  text-align: right;
}

/* Footer */
.siteFooter {
  background: var(--vt-surface-2);
  padding-top: 5rem;
  padding-bottom: 5rem;
}

.footerGrid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 2rem;
}

.footerCol h5 {
  margin-bottom: 1rem;
  color: var(--vt-ink);
  font-size: 20px;
}

.footerCol p,
.footerCol a {
  color: var(--vt-ink-soft);
  font-size: 16px;
  font-weight: 300;
  letter-spacing: 0.5px;
}

.copyright {
  margin-top: 2rem;
  text-align: center;
}

.copyright p {
  color: var(--vt-ink-soft);
  font-size: 14px;
}

/* Responsive */
@media screen and (min-width: 1600px) {
  .heroTrack {
    height: 740px;
  }
}

@media screen and (max-width: 991px) {
  .root {
    padding-top: 74px;
  }

  .root h1 {
    font-size: 38px;
  }

  .root h2 {
    font-size: 32px;
  }

  .root h3 {
    font-size: 26px;
  }

  .root h4 {
    font-size: 24px;
  }

  .root h5 {
    font-size: 20px;
  }

  .root h6 {
    font-size: 18px;
  }

  .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }

  .nav {
    padding-top: 10px;
    padding-bottom: 10px;
  }

  .navLinks a {
    padding-top: 5px;
    padding-bottom: 10px;
  }

  .heroTrack {
    height: auto;
  }

  .heroText {
    position: relative;
    bottom: 100px;
    left: 0;
    width: auto;
    margin-bottom: -100px;
    padding: 2rem;
  }

  .featured-circle {
    width: 320px;
    height: 320px;
  }

  .footerGrid {
    grid-template-columns: 1fr 1fr;
  }
}

@media screen and (max-width: 767px) {
  .heroText {
    padding: 1.5rem;
  }

  .timeline::before {
    top: 60px;
    left: 33px;
    height: 90%;
    transform: translateX(-50%);
  }

  .timelineNode.odd .timelineContent,
  .timelineNode.even .timelineContent {
    text-align: left;
  }

  .timelineNode.even {
    flex-direction: row;
  }

  .timelineNode {
    flex-wrap: wrap;
    justify-content: flex-start;
  }

  .timelineContent {
    width: 100%;
    margin-left: 50px;
  }

  .timelineIconWrap {
    position: absolute;
    left: -10px;
    top: 60px;
    width: 75px;
    height: 75px;
  }

  .timelineIcon::after {
    width: 10px;
    height: 10px;
  }

  .timelineDate {
    width: 100%;
    padding-left: 50px;
    text-align: left !important;
  }

  .footerGrid {
    grid-template-columns: 1fr;
  }
}

@media screen and (max-width: 575px) {
  .timeline::before {
    left: 57px;
    height: 87%;
  }

  .timelineIconWrap {
    left: -10px;
    width: 70px;
    height: 70px;
  }

  .timelineIcon::after {
    width: 8px;
    height: 8px;
  }
}

@media screen and (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }

  .heroLinks .customLink {
    font-size: 12px;
    line-height: 30px;
    margin-right: 12px;
    padding: 0 25px;
  }

  .contactPhone {
    font-size: 12px;
  }
}

@media screen and (max-width: 360px) {
  .timeline::before {
    left: 42px;
  }
}
